实现

```python
def fill_default_arguments(arguments: Dict[str, Any], schema: Dict[str, Any]) -> Dict[str, Any]:
    """
    根据 Schema 自动填充缺失参数的默认值。
    Args:
        arguments: 解析出的参数字典
        schema: 工具 Schema，包含 parameters 字段
    Returns:
        填充后的参数字典
    """
    filled = arguments.copy()
    params_schema = schema.get("parameters", {})
    for param_name, param_info in params_schema.items():
        if param_name not in filled and "default" in param_info:
            filled[param_name] = param_info["default"]
    return filled

# 示例 Schema
schema = {
    "name": "search",
    "parameters": {
        "query": {"type": "str", "required": True},
        "max_results": {"type": "int", "default": 10},
        "safe_search": {"type": "bool", "default": True}
    }
}

# 用户只提供了 query
parsed_args = {"query": "天气"}
filled_args = fill_default_arguments(parsed_args, schema)
print(filled_args)  # {'query': '天气', 'max_results': 10, 'safe_search': True}
```

