from typing import Callable, Dict, Any

class ToolRegistry:
    def __init__(self):
        self._tools: Dict[str, Callable] = {}

    def register(self, name: str, func: Callable):
        """注册一个工具函数"""
        self._tools[name] = func

    def call(self, name: str, *args, **kwargs) -> Any:
        """
        根据名称调用工具函数。
        如果函数不存在，抛出 ValueError。
        如果执行出错，捕获异常并返回错误信息字符串。
        """
        if name not in self._tools:
            raise ValueError(f"工具 '{name}' 未注册")
        try:
            return self._tools[name](*args, **kwargs)
        except Exception as e:
            return f"工具执行错误: {type(e).__name__}: {str(e)}"

    def list_tools(self) -> list:
        """列出所有已注册的工具名称"""
        return list(self._tools.keys())

# 示例
def search(query: str, max_results: int = 10) -> str:
    return f"搜索 '{query}' 的前 {max_results} 条结果"

registry = ToolRegistry()
registry.register("search", search)

print(registry.call("search", query="AI", max_results=5))
# 调用未注册工具
try:
    registry.call("unknown")
except ValueError as e:
    print(e)
# 模拟异常
def faulty():
    raise RuntimeError("网络错误")
registry.register("faulty", faulty)
print(registry.call("faulty"))
```

要点

- register 可以接受任意可调用对象，包括 lambda、类方法等。

- call 方法返回正常结果，或捕获异常并返回描述性错误字符串，便于 LLM 根据错误信息调整后续行为。

