参数提取是工具调用的关键前置步骤。我们可以为每个参数预定义一组提取规则（如正则模式、关键词定位等）。例如，工具 search 有一个参数 query，可以设计规则：匹配引号内的内容，或者匹配“搜索xxx”中的 xxx。

实现

```python
import re
from typing import Dict, Any

class ParamExtractor:
    def __init__(self):
        # 为每个工具定义参数提取规则：参数名 -> 正则模式
        self.rules = {
            "search": {
                "query": r'搜索["\u201c](.+?)["\u201d]|搜索(.+?)(?:$|\n)|查找["\u201c](.+?)["\u201d]',
                "max_results": r'(\d+)条|前(\d+)条'
            },
            "weather": {
                "city": r'(?:城市|地点|地方)[：:]\s*(.+?)(?:$|\n|，|。)',
                "date": r'(\d{4}-\d{2}-\d{2})'
            }
        }

    def extract(self, tool_name: str, user_input: str) -> Dict[str, Any]:
        """根据工具名和用户输入提取参数字典"""
        if tool_name not in self.rules:
            return {}
        params = {}
        for param, pattern in self.rules[tool_name].items():
            match = re.search(pattern, user_input)
            if match:
                # 取第一个非None的捕获组
                value = next((g for g in match.groups() if g is not None), None)
                if value:
                    params[param] = value.strip()
        return params

# 示例
extractor = ParamExtractor()
print(extractor.extract("search", "帮我搜索“人工智能最新进展”，显示前5条"))
# {'query': '人工智能最新进展', 'max_results': '5'}
print(extractor.extract("weather", "查询城市：上海 的天气，日期 2025-01-15"))
# {'city': '上海', 'date': '2025-01-15'}
```

