验证器需要检查：

- 函数名是否在 Schema 中注册。

- 所有必填参数是否都已提供。

- 提供的每个参数的类型是否与 Schema 匹配。

- 不应出现未定义的参数（可选，可以忽略多余参数或报错）。

实现

```python
from typing import Dict, Any, List, Tuple

def validate_tool_call(
    call: Dict[str, Any],
    schemas: Dict[str, Any]
) -> Tuple[bool, List[str]]:
    """
    验证函数调用是否符合 Schema。
    Args:
        call: 包含 "name" 和 "arguments" 字段的字典。
        schemas: 工具 Schema 字典，键为函数名。
    Returns:
        (is_valid, errors): 是否通过验证以及错误信息列表。
    """
    errors = []
    func_name = call.get("name")
    if not func_name:
        errors.append("函数调用缺少 'name' 字段")
        return False, errors

    schema = schemas.get(func_name)
    if not schema:
        errors.append(f"函数 '{func_name}' 未在 Schema 中定义")
        return False, errors

    params_schema = schema.get("parameters", {})
    arguments = call.get("arguments", {})

    # 检查必填参数
    for param_name, param_info in params_schema.items():
        if param_info.get("required", False):
            if param_name not in arguments:
                errors.append(f"缺少必填参数 '{param_name}'")

    # 检查参数类型
    type_map = {
        "str": str,
        "int": int,
        "float": float,
        "bool": bool,
        "list": list,
        "dict": dict
    }
    for param_name, value in arguments.items():
        if param_name not in params_schema:
            # 可选：忽略未知参数 或 报错
            # errors.append(f"提供了未定义的参数 '{param_name}'")
            continue
        expected_type = params_schema[param_name].get("type")
        if expected_type and expected_type in type_map:
            if not isinstance(value, type_map[expected_type]):
                errors.append(
                    f"参数 '{param_name}' 类型错误：期望 {expected_type}，实际 {type(value).__name__}"
                )

    return len(errors) == 0, errors

# 示例
schemas = {
    "search": {
        "parameters": {
            "query": {"type": "str", "required": True},
            "max_results": {"type": "int", "required": False}
        }
    }
}

call1 = {"name": "search", "arguments": {"query": "天气"}}
call2 = {"name": "search", "arguments": {"max_results": 5}}
call3 = {"name": "unknown", "arguments": {}}
call4 = {"name": "search", "arguments": {"query": 123}}

